export const SHAPE_BY_GEOM: Record<string, ShapePreset> = Object.fromEntries(
  SHAPE_PRESETS.map((s) => [s.geom, s]),
)

/** the presets of one gallery group, in the original's order */
export function shapesInGroup(group: string): ShapePreset[] {
  return SHAPE_PRESETS.filter((s) => s.group === group)
}
